const input = 'w-full min-w-0 rounded-lg border border-stone-300 bg-white px-3 py-2.5 text-sm text-stone-900 outline-none transition focus:border-amber-600 focus:ring-2 focus:ring-amber-100';
const label = 'mb-1.5 block text-xs font-semibold text-stone-700';
const Section = ({ title, children, hidden = false }: { title: string; children: React.ReactNode; hidden?: boolean }) => <section hidden={hidden} className="space-y-4"><h2 className="border-l-4 border-amber-500 bg-emerald-950 px-4 py-2.5 text-sm font-bold uppercase tracking-wide text-white">{title}</h2>{children}</section>;

export const Register: React.FC = () => {
  const { t, language, isRtl } = useTranslation();
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState('');
  const [stepValidationError, setStepValidationError] = useState('');
  const [regions, setRegions] = useState<Region[]>([]);
  const [regionsLoading, setRegionsLoading] = useState(true);
  const [regionsError, setRegionsError] = useState('');

  useEffect(() => {
    let active = true;
    api.getRegions()
      .then((items) => { if (active && Array.isArray(items)) setRegions(items); })
      .catch(() => { if (active) setRegionsError('Unable to load regions. Please refresh and try again.'); })
      .finally(() => { if (active) setRegionsLoading(false); });
    return () => { active = false; };
  }, []);
  const { register, handleSubmit, watch, trigger, setValue, control, formState: { errors } } = useForm<Record<string, any>>({ mode: 'onChange', reValidateMode: 'onChange', shouldUnregister: false, defaultValues: { membershipCategory: '', gender: '', idType: 'fayda', employmentStatus: 'Employed', declaration: false, phone: '', secondaryPhone: '', emergencyContactPhone: '', alternateEmergencyPhone: '', education: [], certifications: [], experience: [] } });
  const educationArray = useFieldArray({ control, name: 'education' });
  const certificationArray = useFieldArray({ control, name: 'certifications' });
  const experienceArray = useFieldArray({ control, name: 'experience' });
  const [step, setStep] = useState(0);
  const totalSteps = 9;
  const ethiopianNationality = /ethiop/i.test(String(watch('nationality') || ''));
  useEffect(() => {
    if (!ethiopianNationality) return;
    (['phone','secondaryPhone','emergencyContactPhone','alternateEmergencyPhone'] as const).forEach((key) => {
      const current = String(watch(key) || '');
      if (!current) setValue(key, '+251');
      else if (!current.startsWith('+251')) setValue(key, '+251' + current.replace(/\D/g, '').replace(/^251/, '').slice(0, 9));
    });
  }, [ethiopianNationality, setValue]);
  const lang = copy[language] || copy.en;
  const tr = (key: string) => lang[key] || copy.en[key] || t(`register.${key}`, key);
  const renderField = ({ name, title, type = 'text', required = false, placeholder = '' }: { name: string; title: string; type?: string; required?: boolean; placeholder?: string }) => <label className="block"><span className={label}>{title}{required && <b className="text-red-600"> *</b>}</span><input {...register(name, { required: required ? `${title} is required` : false, ...(type === 'email' ? { pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: 'Enter a valid email address' } } : {}) })} type={type} placeholder={placeholder} className={input} />{(errors as any)[name] && <span className="mt-1 block text-xs text-red-600">{String((errors as any)[name]?.message || 'Please check this field.')}</span>}</label>;
  // Invoke this renderer directly in JSX. A nested <PhoneField /> component would be
  // recreated on every form render and cause the input to lose focus while typing.
  const renderPhoneField = ({ name, title, required = false }: { name: string; title: string; required?: boolean }) => <label className="block"><span className={label}>{title}{required && <b className="text-red-600"> *</b>}</span><input type="tel" inputMode="tel" placeholder={ethiopianNationality ? '+2519XXXXXXXX' : '+country code'} className={input} {...register(name, { required: required ? `${title} is required` : false, validate: (v: string) => { if (!v) return required ? `${title} is required` : true; return ethiopianNationality ? (/^\+251[79]\d{8}$/.test(v) || 'Use +251 followed by exactly 9 digits starting with 7 or 9.') : (/^\+[1-9]\d{6,14}$/.test(v) || 'Enter a valid international number in +country-code format.'); }, onChange: (e) => { const raw = e.target.value; if (ethiopianNationality) { const digits = raw.replace(/\D/g, '').replace(/^251/, '').slice(0, 9); e.target.value = '+251' + digits; } else { const digits = raw.replace(/[^\d+]/g, '').replace(/(?!^)\+/g, '').slice(0, 16); e.target.value = digits; } } })} />{(errors as any)[name] && <span className="mt-1 block text-xs text-red-600">{String((errors as any)[name]?.message || 'Please check this field.')}</span>}</label>;
  const renderSelect = ({ name, title, options, required = false }: { name: string; title: string; options: [string, string][]; required?: boolean }) => <label className="block"><span className={label}>{title}{required && <b className="text-red-600"> *</b>}</span><select {...register(name, { required: required ? `${title} is required` : false })} className={input}><option value="">{t('common.selectOption', 'Select an option')}</option>{options.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select>{(errors as any)[name] && <span className="mt-1 block text-xs text-red-600">{String((errors as any)[name]?.message || `${title} is required.`)}</span>}</label>;
  const renderTextArea = ({ name, title, rows = 2 }: { name: string; title: string; rows?: number }) => <label className="block"><span className={label}>{title}</span><textarea {...register(name)} rows={rows} className={input} /></label>;
  const renderCheckGroup = ({ name, title, options }: { name: string; title: string; options: [string, string][] }) => <fieldset><legend className={label}>{title}</legend><div className="grid gap-2 sm:grid-cols-2">{options.map(([v, l]) => <label key={v} className="flex items-start gap-2 rounded-lg border border-stone-200 p-2.5 text-sm text-stone-700"><input type="checkbox" value={v} {...register(name)} className="mt-0.5 accent-emerald-900"/><span>{l}</span></label>)}</div></fieldset>;
  const renderFileSlot = ({ name, title, multiple = false, required = false }: { name: string; title: string; multiple?: boolean; required?: boolean }) => {
    const files = watch(name) as FileList | File[] | undefined;
    const fileError = (errors as any)[name];
    return <div className="min-w-0">
      <label className={`flex cursor-pointer flex-col gap-2 rounded-xl border-2 border-dashed ${fileError ? 'border-red-500 bg-red-50' : 'border-stone-300 bg-stone-50'} p-4 transition hover:border-amber-500`}>
        <span className="flex items-center gap-2 text-sm font-semibold text-stone-800"><UploadCloud className="h-5 w-5 text-emerald-900"/>{title}{required && <b className="text-red-600"> *</b>}</span>
        <span className="text-xs text-stone-500">PDF, JPG, JPEG, PNG · {multiple ? 'Multiple files allowed' : 'One file'}</span>
        <span className="flex items-center gap-2 break-all text-xs font-semibold text-emerald-900"><FileText className="h-4 w-4 shrink-0"/>{files?.length ? Array.from(files).map(f => f.name).join(', ') : tr('upload')}</span>
        <input type="file" accept=".pdf,.jpg,.jpeg,.png" multiple={multiple} aria-invalid={Boolean(fileError)} aria-describedby={fileError ? `${name}-error` : undefined} {...register(name, { validate: required ? (value: FileList | File[] | undefined) => Boolean(value && value.length > 0) || `${title} is required. Please choose a file.` : undefined })} className="sr-only"/>
      </label>
      {fileError && <p id={`${name}-error`} role="alert" className="mt-2 flex items-start gap-1 text-xs font-medium text-red-700"><AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0"/>{String(fileError.message || `${title} is required. Please choose a file.`)}</p>}
    </div>;
  };
  const onSubmit = async (values: Record<string, any>) => {
    setBusy(true); setError('');
    const form = document.getElementById('official-ohpea-form') as HTMLFormElement;
    const payload = new FormData(form);
    payload.set('preferredLanguage', ['en', 'om', 'am', 'ar', 'fr'].includes(language) ? language : 'en');
    payload.set('fullName', values.fullName || '');
    payload.set('email', values.email || '');
    payload.set('phone', values.phone || '');
    payload.set('idType', values.idType || 'fayda');
    payload.set('idNumber', values.nationalId || '');
    payload.set('gender', String(values.gender || '').toLowerCase());
    payload.set('membershipCategory', values.membershipCategory || '');
    payload.set('regionId', values.region || '');
    payload.set('region', values.region || '');
    payload.set('organizationName', values.organization || '');
    payload.set('town', values.cityTown || '');
    payload.set('consent', values.declaration ? 'true' : 'false');

    // Preserve the complete official form as JSON; binary files remain multipart uploads.
    const toJsonSafe = (value: unknown): unknown => {
      if (typeof File !== 'undefined' && value instanceof File) return undefined;
      if (typeof FileList !== 'undefined' && value instanceof FileList) return undefined;
      if (Array.isArray(value)) return value.map(toJsonSafe).filter((item) => item !== undefined);
      if (value && typeof value === 'object') {
        return Object.fromEntries(Object.entries(value as Record<string, unknown>)
          .map(([key, item]) => [key, toJsonSafe(item)])
          .filter(([, item]) => item !== undefined));
      }
      return value;
    };
    const officialData = toJsonSafe({
      ...values,
      preferredLanguage: ['en', 'om', 'am', 'ar', 'fr'].includes(language) ? language : 'en',
      regionId: values.region || '',
      region: values.region || '',
      idType: values.idType || 'fayda',
      idNumber: values.nationalId || '',
      // Alias structured collections to keys the backend does not overwrite
      // when it adds its legacy flat registration columns.
      educationRecords: values.education || [],
      certificationRecords: values.certifications || [],
      experienceRecords: values.experience || [],
      languageProficiency: values.language || {},
      paymentMethods: values.paymentMethod || [],
    });
    payload.set('officialFormData', JSON.stringify(officialData));
    try { await api.submitRegistration(payload); setDone(true); window.scrollTo({ top: 0, behavior: 'smooth' }); }
    catch (e) { setError(e instanceof ApiError ? e.message : e instanceof Error ? e.message : 'Unable to submit application.'); }
    finally { setBusy(false); }
  };

  const regionOptions: [string, string][] = regions.map((region) => {
    const localizedName = region.name;
    const name = typeof localizedName === 'string'
      ? localizedName
      : localizedName?.[language as keyof typeof localizedName] || localizedName?.en || localizedName?.om || localizedName?.am || region.id;
    return [region.id, name] as [string, string];
  });

  const categoryOptions: [string, string][] = [['Professional', tr('professional')], ['Entrepreneur', tr('entrepreneur')], ['Corporate', tr('corporate')], ['Associate', tr('associate')]];
  const industries: [string, string][] = [['Hotel / Resort / Lodge', tr('hotel')], ['Restaurant / Cafe / Catering', tr('restaurant')], ['Tour & Travel Agency', tr('tour')], ['Event Management & MICE', tr('events')], ['Hospitality Education & Training', tr('education')], ['Supply Chain / Hospitality Tech', tr('supply')], ['Eco-Tourism / Cultural Heritage', tr('eco')], ['Other', tr('other')]];
  const expertise: [string, string][] = [['Hotel & Resort Operations', tr('expertise1')], ['Food & Beverage / Culinary Arts', tr('expertise2')], ['Eco-Tourism & Cultural Tourism', tr('expertise3')], ['Hospitality Entrepreneurship & Planning', tr('expertise4')], ['Marketing, Branding & Digital Presence', tr('expertise5')], ['Human Resources & Staff Training', tr('expertise6')], ['Quality Assurance & Customer Experience', tr('expertise7')], ['Financial & Revenue Management', tr('expertise8')], ['Event & Conference Management', tr('expertise9')], ['Other', tr('other')]];
  const interests: [string, string][] = [['Networking & Business Partnerships', tr('interest1')], ['Professional Development & Workshops', tr('interest2')], ['Mentorship', tr('interest3')], ['Policy Advocacy & Industry Representation', tr('interest4')], ['Access to Finance & Investment', tr('interest5')], ['Research & Oromia Tourism Promotion', tr('interest6')], ['Volunteering on Association Committees', tr('interest7')], ['Job Placement & Career Support', tr('interest8')]];
  const paymentOptions: [string, string][] = [['Bank Deposit/Transfer', tr('transfer')], ['Mobile Money', tr('mobileMoney')], ['Cash at Office', tr('cash')]];
  const bankOptions: [string, string][] = [['Cooperative Bank of Oromia (CBO)',tr('cbo')],['Commercial Bank of Ethiopia (CBE)',tr('cbe')],['Awash Bank',tr('awash')],['Mobile Money (Telebirr / CBE Birr / E-Birr)',tr('mobileMoney')],['Cash at Office',tr('cash')]];
  const feeRows = [['Associate / Student Member','200 ETB (or approved rate)','500 ETB (or approved rate)','700 ETB'],['Hospitality Professional','500 ETB (or approved rate)','1,500 ETB (or approved rate)','2,000 ETB'],['Hospitality Entrepreneur / Business Owner','1,000 ETB (or approved rate)','3,000 ETB (or approved rate)','4,000 ETB'],['Corporate / Institutional Member','2,500 ETB (or approved rate)','10,000 ETB (or approved rate)','12,500 ETB']];
  const feeCategoryByValue: Record<string, string> = { Associate: 'Associate / Student Member', Professional: 'Hospitality Professional', Entrepreneur: 'Hospitality Entrepreneur / Business Owner', Corporate: 'Corporate / Institutional Member' };
  const selectedFeeRow = feeRows.find(([category]) => category === feeCategoryByValue[String(watch('membershipCategory') || '')]);
  const renderTable = ({ headers, rows }: { headers: string[]; rows: React.ReactNode[][] }) => <div className="overflow-x-auto rounded-lg border border-stone-200"><table className="w-full min-w-[680px] border-collapse text-left text-xs"><thead className="bg-stone-100 text-emerald-950"><tr>{headers.map(h => <th key={h} className="border-b border-stone-200 p-3 font-bold">{h}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={i} className="odd:bg-white even:bg-stone-50">{row.map((cell, j) => <td key={j} className="border-t border-stone-200 p-2.5 align-top">{cell}</td>)}</tr>)}</tbody></table></div>;
  const rowInput = (name: string, type = 'text', disabled = false) => <input {...register(name)} type={type} disabled={disabled} className={`${input} min-w-[100px] disabled:cursor-not-allowed disabled:bg-stone-100`} />;

  return <div className="pb-16" dir={isRtl ? 'rtl' : 'ltr'}><PageBanner title={t('register.title')} subtitle={t('register.subtitle')} breadcrumbs={[{ label: t('nav.home'), to: '/' }, { label: t('nav.membership'), to: '/membership' }, { label: tr('official') }]} />
    <div className="mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-8">{done ? <div className="rounded-2xl border border-emerald-200 bg-white p-10 text-center shadow-sm"><CheckCircle2 className="mx-auto mb-4 h-16 w-16 text-emerald-700"/><h2 className="text-2xl font-bold text-emerald-950">{tr('success')}</h2><p className="mt-2 text-stone-600">{tr('successText')}</p></div> : <div className="overflow-hidden rounded-2xl border border-stone-200 bg-white shadow-sm">
      <div className="border-b-4 border-amber-500 bg-emerald-950 px-5 py-7 text-white sm:px-8"><div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-amber-300">OHPEA</p><h1 className="mt-2 text-xl font-extrabold sm:text-2xl">{tr('official')}</h1><p className="mt-2 text-sm text-emerald-100">{tr('tagline')}</p></div><div className="rounded-xl border border-white/20 bg-white/10 px-4 py-3 text-xs">{t('register.subtitle')}</div></div></div>
      <form id="official-ohpea-form" onSubmit={handleSubmit(onSubmit, (invalidFields) => {
        const firstInvalidField = Object.keys(invalidFields)[0] || '';
        const stepForField: Record<string, number> = {
          membershipCategory: 0, fullName: 0, gender: 0, dateOfBirth: 0, nationality: 0, nationalId: 0, idType: 0, phone: 0, secondaryPhone: 0, email: 0, region: 0, zoneSubCity: 0, woreda: 0, cityTown: 0, emergencyContactName: 0, emergencyRelationship: 0, emergencyContactPhone: 0, alternateEmergencyPhone: 0,
          employmentStatus: 1, organization: 1, jobTitle: 1, workplaceLocation: 1, yearsInCurrentRole: 1, businessTin: 1, yearEstablishedEmployees: 1, industrySubSectors: 1,
          education: 2, certifications: 3, experience: 4, languagesKnown: 5, language: 5, technicalSkills: 5, coreSkills: 5, areasOfExpertise: 6, areasOfInterest: 6,
          paymentMethod: 7, bankPlatformUsed: 7, transactionReference: 7, amountPaid: 7, paymentDate: 7, passportPhoto: 8, idDocument: 8, cvCompanyProfile: 8, academicCertificates: 8, professionalLicensesBusinessRegistration: 8, paymentProof: 8, applicantFullName: 8, applicantSignature: 8, declarationDate: 8, declaration: 8,
        };
        setStep(stepForField[firstInvalidField] ?? 0);
        setStepValidationError('Please correct the highlighted fields in this section before continuing.');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      })} className="space-y-8 p-4 sm:p-8">
        <p className="text-sm text-stone-600">{tr('intro')}</p>
        
        <Section hidden={step !== 0} title={tr('s1')}><p className="text-sm text-stone-600">{tr('categoryHelp')}</p><div className="grid gap-3 sm:grid-cols-2">{categoryOptions.map(([v,l])=><label key={v} className="flex items-start gap-3 rounded-xl border border-stone-200 p-4 text-sm"><input type="radio" value={v} {...register('membershipCategory',{required:true})} className="mt-1 accent-emerald-900"/><span className="font-semibold text-stone-800">{l}</span></label>)}</div>{errors.membershipCategory && <p className="text-xs text-red-600">Please select a membership category.</p>}</Section>
        <Section hidden={step !== 0} title={tr('s2')}>{regionsLoading && <p className="text-xs text-stone-500">Loading regions…</p>}{regionsError && <p role="alert" className="text-xs text-red-600">{regionsError}</p>}<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{renderField({ name: 'fullName', title: tr('fullName'), required: true })}{renderSelect({ name: 'gender', title: tr('gender'), required: true, options: [["Male",tr('male')],["Female",tr('female')]] })}{renderField({ name: 'dateOfBirth', title: tr('dob'), type: 'date' })}{renderField({ name: 'nationality', title: tr('nationality') })}{renderField({ name: 'nationalId', title: tr('nationalId'), required: true })}{renderSelect({ name: 'idType', title: tr('idType'), options: [["fayda","Fayda ID"],["passport","Passport"],["kebele","Kebele ID"],["driver","Driver License"]] })}{renderPhoneField({ name: 'phone', title: tr('phone'), required: true })}{renderPhoneField({ name: 'secondaryPhone', title: tr('secondaryPhone') })}{renderField({ name: 'email', title: tr('email'), type: 'email', required: true })}{renderSelect({ name: 'region', title: tr('region'), required: true, options: regionOptions })}{renderField({ name: 'zoneSubCity', title: tr('zone') })}{renderField({ name: 'woreda', title: tr('woreda') })}{renderField({ name: 'cityTown', title: tr('city') })}{renderField({ name: 'emergencyContactName', title: tr('emergencyName') })}{renderField({ name: 'emergencyRelationship', title: tr('relationship') })}{renderPhoneField({ name: 'emergencyContactPhone', title: tr('emergencyPhone') })}{renderPhoneField({ name: 'alternateEmergencyPhone', title: tr('alternatePhone') })}</div></Section>
        <Section hidden={step !== 1} title={tr('s3')}><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{renderSelect({ name: 'employmentStatus', title: tr('employment'), options: [["Employed",tr('employed')],["Self-Employed",tr('selfEmployed')],["Freelancer",tr('freelancer')],["Job Seeker",tr('jobSeeker')]] })}{renderField({ name: 'organization', title: tr('organization') })}{renderField({ name: 'jobTitle', title: tr('jobTitle') })}{renderField({ name: 'workplaceLocation', title: tr('workplace') })}{renderField({ name: 'yearsInCurrentRole', title: tr('yearsRole'), type: 'number' })}{renderField({ name: 'businessTin', title: tr('tin') })}{renderField({ name: 'yearEstablishedEmployees', title: tr('established') })}</div>{renderCheckGroup({ name: 'industrySubSectors', title: tr('industry'), options: industries })}</Section>
        <Section hidden={step !== 2} title={tr('s4')}><p className="text-xs text-stone-500">{tr('addRows')}</p>{renderTable({ headers: ['#',tr('qualification'),tr('field'),tr('institution'),tr('country'),tr('graduation'),''], rows: educationArray.fields.map((f,i)=>[String(i+1),rowInput(`education[${i}].qualification`),rowInput(`education[${i}].field`),rowInput(`education[${i}].institution`),rowInput(`education[${i}].country`),rowInput(`education[${i}].graduation`,'number'),<button type="button" onClick={()=>educationArray.remove(i)} className="text-xs font-semibold text-red-600">Remove</button>]) })}<button type="button" onClick={()=>educationArray.append({qualification:'',field:'',institution:'',country:'',graduation:''})} className="rounded-lg border border-emerald-900 px-3 py-2 text-xs font-semibold text-emerald-900">+ Add education</button></Section>
        <Section hidden={step !== 3} title={tr('s5')}>{renderTable({ headers: ['#',tr('certification'),tr('issuer'),tr('issueDate'),tr('expiryDate'),''], rows: certificationArray.fields.map((f,i)=>[String(i+1),rowInput(`certifications[${i}].name`),rowInput(`certifications[${i}].issuer`),rowInput(`certifications[${i}].issueDate`,'date'),rowInput(`certifications[${i}].expiryDate`,'date'),<button type="button" onClick={()=>certificationArray.remove(i)} className="text-xs font-semibold text-red-600">Remove</button>]) })}<button type="button" onClick={()=>certificationArray.append({name:'',issuer:'',issueDate:'',expiryDate:''})} className="rounded-lg border border-emerald-900 px-3 py-2 text-xs font-semibold text-emerald-900">+ Add certification</button></Section>
        <Section hidden={step !== 4} title={tr('s6')}>{renderTable({ headers: ['#',tr('experienceOrg'),tr('jobTitle'),tr('responsibilities'),tr('startDate'),tr('endDate'),'Currently working?',''], rows: experienceArray.fields.map((f,i)=>[String(i+1),rowInput(`experience[${i}].organization`),rowInput(`experience[${i}].jobTitle`),rowInput(`experience[${i}].responsibilities`),rowInput(`experience[${i}].startDate`,'date'),rowInput(`experience[${i}].endDate`,'date',!!watch(`experience.${i}.currentlyWorking`)),<label className="flex items-center gap-1 text-xs"><input type="checkbox" {...register(`experience.${i}.currentlyWorking`)} onChange={(e)=>{setValue(`experience.${i}.currentlyWorking`,e.target.checked); if(e.target.checked) setValue(`experience.${i}.endDate`,'');}}/>Yes</label>,<button type="button" onClick={()=>experienceArray.remove(i)} className="text-xs font-semibold text-red-600">Remove</button>]) })}<button type="button" onClick={()=>experienceArray.append({organization:'',jobTitle:'',responsibilities:'',startDate:'',endDate:'',currentlyWorking:false})} className="rounded-lg border border-emerald-900 px-3 py-2 text-xs font-semibold text-emerald-900">+ Add experience</button><div className="max-w-sm">{renderField({ name: 'totalExperienceYears', title: tr('totalYears'), type: 'number' })}</div></Section>
        <Section hidden={step !== 5} title={tr('s7')}><p className="text-xs text-stone-500">{tr('languageProficiency')}</p>{renderCheckGroup({ name: 'languagesKnown', title: 'Languages you speak', options: [["Afaan Oromoo",tr('afaan')],["Amharic",tr('amharic')],["English",tr('english')],["Arabic",tr('arabic')],["French",tr('french')],["Other",tr('other')]] })}<div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[['afaan',tr('afaan')],['amharic',tr('amharic')],['english',tr('english')],['arabic',tr('arabic')],['french',tr('french')]].map(([key,title])=>renderSelect({ name: `language.${key}`, title: `${title} — proficiency`, options: [["Basic","Basic"],["Conversational","Conversational"],["Fluent","Fluent"],["Native","Native"]] }))}</div>{renderField({ name: 'language.otherLanguage', title: 'Other language(s)' })}{renderTextArea({ name: 'technicalSkills', title: tr('technical') })}{renderTextArea({ name: 'coreSkills', title: tr('core') })}</Section>
        <Section hidden={step !== 6} title={tr('s8')}>{renderCheckGroup({ name: 'areasOfExpertise', title: tr('expertise'), options: expertise })}{renderCheckGroup({ name: 'areasOfInterest', title: tr('interests'), options: interests })}</Section>
        <Section hidden={step !== 7} title={tr('s9')}><p className="text-xs text-amber-800">{tr('feeNote')}</p>{renderTable({ headers: [tr('feeCategory'),tr('regFee'),tr('annual'),tr('total')], rows: feeRows.map((r)=>r.map((v)=>v)) })}{selectedFeeRow && <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-stone-800"><p className="font-semibold">Selected membership category: {selectedFeeRow[0]}</p><p className="mt-1">Registration: {selectedFeeRow[1]} · Annual subscription: {selectedFeeRow[2]}</p><p className="mt-1 font-bold text-emerald-950">Total due upon joining: {selectedFeeRow[3]}</p><p className="mt-1 text-xs text-stone-600">Please confirm the current approved tariff with the OHPEA Secretariat before payment.</p></div>}<div className="space-y-2"><h3 className="text-sm font-bold text-stone-800">{tr('bank')}</h3><p className="text-xs text-stone-600">{tr('accountHolder')}</p>{renderTable({ headers: [tr('platform'),tr('account'),tr('branch')], rows: [[tr('cbo'),'To be confirmed by OHPEA Secretariat','To be confirmed by OHPEA Secretariat'],[tr('cbe'),'To be confirmed by OHPEA Secretariat','To be confirmed by OHPEA Secretariat'],[tr('awash'),'To be confirmed by OHPEA Secretariat','To be confirmed by OHPEA Secretariat'],[tr('mobileMoney'),'To be confirmed by OHPEA Secretariat','Include Full Name in Reference']] })}</div><div className="space-y-3"><h3 className="text-sm font-bold text-stone-800">{tr('paymentConfirm')}</h3>{renderSelect({ name: 'paymentMethod', title: tr('paymentMethod'), options: paymentOptions })}<div className="grid gap-4 sm:grid-cols-2">{renderSelect({ name: 'bankPlatformUsed', title: tr('bankUsed'), options: bankOptions })}{renderField({ name: 'transactionReference', title: tr('receipt') })}{renderField({ name: 'amountPaid', title: 'Amount Paid (ETB)', type: 'number' })}{renderField({ name: 'paymentDate', title: 'Payment Date', type: 'date' })}</div></div></Section>
        <Section hidden={step !== 8} title={tr('s10')}><p className="text-sm text-stone-600">{tr('docsHelp')}</p><div className="grid gap-3 md:grid-cols-2">{renderFileSlot({ name: 'passportPhoto', title: tr('photo') })}{renderFileSlot({ name: 'idDocument', title: tr('idCopy'), required: true })}{renderFileSlot({ name: 'cvCompanyProfile', title: tr('cv'), required: true })}{renderFileSlot({ name: 'academicCertificates', title: tr('academicDocs'), multiple: true })}{renderFileSlot({ name: 'professionalLicensesBusinessRegistration', title: tr('licenses'), multiple: true })}{renderFileSlot({ name: 'paymentProof', title: tr('paymentProof') })}</div></Section>
        <Section hidden={step !== 8} title={tr('s11')}><p className="rounded-xl bg-stone-50 p-4 text-sm leading-7 text-stone-700">{tr('declarationText')}</p><div className="grid gap-4 sm:grid-cols-3">{renderField({ name: 'applicantFullName', title: tr('applicantName'), required: true })}{renderField({ name: 'applicantSignature', title: tr('signature'), required: true })}{renderField({ name: 'declarationDate', title: tr('date'), type: 'date', required: true })}</div><label className="flex items-start gap-3 rounded-xl border border-stone-200 p-4 text-sm"><input type="checkbox" {...register('declaration',{required:true})} className="mt-1 accent-emerald-900"/><span>{tr('declarationText')}</span></label>{errors.declaration && <p className="text-xs text-red-600">Please accept the declaration to continue.</p>}</Section>
        <div className="space-y-2 rounded-xl border border-stone-200 bg-stone-50 p-4">
          <div className="flex items-center justify-between text-xs font-semibold text-stone-700"><span>Step {step + 1} of {totalSteps}</span><span>{Math.round(((step + 1) / totalSteps) * 100)}%</span></div>
          <div className="h-2 overflow-hidden rounded-full bg-stone-200"><div className="h-full rounded-full bg-amber-500 transition-all" style={{ width: `${((step + 1) / totalSteps) * 100}%` }} /></div>
        </div>
        {stepValidationError && <div role="alert" aria-live="polite" className="flex items-center gap-2 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700"><AlertCircle className="h-4 w-4 shrink-0"/>{stepValidationError}</div>}
        {error && <div role="alert" aria-live="polite" className="flex items-center gap-2 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-700"><AlertCircle className="h-4 w-4 shrink-0"/>{error}</div>}
        <div className="flex flex-col-reverse gap-3 border-t border-stone-200 pt-5 sm:flex-row sm:items-center sm:justify-between"><p className="text-xs text-stone-500">OHPEA · Official Membership Registration</p><div className="flex gap-2">{step > 0 && <button type="button" onClick={() => { setStepValidationError(''); setStep((v) => Math.max(0, v - 1)); window.scrollTo({ top: 0, behavior: 'smooth' }); }} className="rounded-xl border border-stone-300 px-5 py-3 text-sm font-semibold text-stone-700">Back</button>}{step < totalSteps - 1 ? <button type="button" onClick={async () => {
            const fieldsByStep: Record<number, string[]> = {
              0: ['membershipCategory','fullName','gender','dateOfBirth','nationality','nationalId','idType','phone','secondaryPhone','email','region','zoneSubCity','woreda','cityTown','emergencyContactName','emergencyRelationship','emergencyContactPhone','alternateEmergencyPhone'],
              1: ['employmentStatus','organization','jobTitle','workplaceLocation','yearsInCurrentRole','businessTin','yearEstablishedEmployees','industrySubSectors'],
              2: educationArray.fields.flatMap((_, i) => [`education.${i}.qualification`,`education.${i}.field`,`education.${i}.institution`,`education.${i}.country`,`education.${i}.graduation`]),
              3: certificationArray.fields.flatMap((_, i) => [`certifications.${i}.name`,`certifications.${i}.issuer`,`certifications.${i}.issueDate`,`certifications.${i}.expiryDate`]),
              4: experienceArray.fields.flatMap((_, i) => [`experience.${i}.organization`,`experience.${i}.jobTitle`,`experience.${i}.responsibilities`,`experience.${i}.startDate`,`experience.${i}.endDate`,`experience.${i}.currentlyWorking`]).concat(['totalExperienceYears']),
              5: ['languagesKnown','language.afaan','language.amharic','language.english','language.arabic','language.french','language.otherLanguage','technicalSkills','coreSkills'],
              6: ['areasOfExpertise','areasOfInterest'],
              7: ['paymentMethod','bankPlatformUsed','transactionReference','amountPaid','paymentDate'],
              8: ['passportPhoto','idDocument','cvCompanyProfile','academicCertificates','professionalLicensesBusinessRegistration','paymentProof','applicantFullName','applicantSignature','declarationDate','declaration'],
            };
            const currentFields = fieldsByStep[step] || [];
            const ok = currentFields.length === 0 || await trigger(currentFields, { shouldFocus: true });
            if (!ok) { setStepValidationError('Please correct the highlighted fields in this section before continuing.'); return; }
            setStepValidationError('');
            setStep((v) => Math.min(totalSteps - 1, v + 1));
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }} className="rounded-xl bg-emerald-950 px-7 py-3 text-sm font-bold text-white">Next</button> : <button type="submit" disabled={busy} className="inline-flex items-center justify-center gap-2 rounded-xl bg-amber-500 px-7 py-3.5 text-sm font-bold text-emerald-950 shadow-sm transition hover:bg-amber-400 disabled:opacity-60">{busy ? tr('submitting') : tr('submit')}<CheckCircle2 className="h-4 w-4"/></button>}</div></div>
      </form></div>}</div></div>;
};
